"use server"

import { revalidatePath } from "next/cache"

const store = globalThis as unknown as { notificationsEnabled?: boolean }

export async function toggleNotifications() {
  store.notificationsEnabled = !(store.notificationsEnabled ?? false)
  revalidatePath("/")
}

import { toggleNotifications } from "./actions"

const store = globalThis as unknown as { notificationsEnabled?: boolean }

export default function Home() {
  const enabled = store.notificationsEnabled ?? false

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Email notifications: <strong>{enabled ? "On" : "Off"}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">{enabled ? "Turn off" : "Turn on"}</button>
      </form>
    </main>
  )
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
